class Solution {
  public long countPairs(String[] words) {
    java.util.HashMap<String, Integer> groups = new java.util.HashMap<>();
    long total = 0;
    for (String w : words) {
      char[] key = new char[w.length()];
      int shift = w.charAt(0) - 'a';
      for (int i = 0; i < key.length; i++)
        key[i] = (char) ('a' + (w.charAt(i) - 'a' - shift + 26) % 26);
      String k = new String(key);
      int c = groups.getOrDefault(k, 0);
      total += c;
      groups.put(k, c + 1);
    }
    return total;
  }
}
